import sys,os,json,subprocess,time,threading,hashlib,datetime,types,shutil,re
from pathlib import Path
ROOT=Path.cwd();CONTROL=ROOT/'build/stage3-fourth-control';OUT=ROOT/'docs/reports/bench';CHECK=OUT/'S2-stage3-checks.json';data=json.loads(CHECK.read_text());COMMIT=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();assert COMMIT==data['sourceCommit'];assert data['affectedSelfTests']['viewer']['verdict'] in ('pass','environment') and data['affectedSelfTests']['panel']['verdict']=='pass'
BINARY=Path(data['appBuild']['binary']);EXPECTED=data['appBuild']['binarySHA256'];assert hashlib.sha256(BINARY.read_bytes()).hexdigest()==EXPECTED
mod=types.ModuleType('acceptance_frozen');mod.__file__=str(ROOT/'scripts/acceptance/run.py');exec(compile(Path(mod.__file__).read_text(),mod.__file__,'exec'),mod.__dict__)
