import os,sys,json,hashlib,subprocess,time,select,re,runpy,datetime,shutil
from pathlib import Path
ROOT=Path.cwd(); CONTROL=ROOT/'build/stage3-fourth-control'; OUT=ROOT/'docs/reports/bench'; CHECK=OUT/'S2-stage3-checks.json'; COMMIT=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def gitobj(ref,path): return subprocess.check_output(['git','rev-parse',f'{ref}:{path}'],text=True).strip()
def save(): CHECK.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def progress(event,**kw):
 d={'at':now(),'runnerPID':os.getpid(),'event':event,**kw}; (CONTROL/'progress.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n'); print(json.dumps(d,ensure_ascii=False),flush=True)
backup=OUT/'before-w37'; backup.mkdir(exist_ok=False)
files=sorted(OUT.glob('S2-T2-*.json'))+[CHECK]; assert len(files)==14
preserved=[]
for p in files:
 target=backup/p.name; shutil.copy2(p,target); assert sha(p)==sha(target); preserved.append({'source':str(p.relative_to(ROOT)),'backup':str(target.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size})
old=json.loads((backup/CHECK.name).read_text()); built=json.loads((OUT/'S2-T3-w37-before.json').read_text())['cleanup']['finalBuiltApp']; BINARY=Path(built['binary']); APP=BINARY.parents[2]
assert COMMIT==built['sourceCommit']; assert sha(BINARY)==built['binarySHA256']
sig=subprocess.run(['codesign','-d','--verbose=4',str(APP)],capture_output=True,text=True); assert built['cdhash'] in sig.stderr
for row in built['sourceFiles']: assert row['gitBlobSHA']==gitobj(COMMIT,row['path']) and row['sha256']==sha(ROOT/row['path'])
data={'stage':'S2-stage3-fourth-acceptance','sourceCommit':COMMIT,'startedAt':now(),'rootTaskBaseline':json.loads((CONTROL/'baseline.json').read_text()),'preservedPreviousEvidence':preserved,'checks':{},'appBuild':{**built,'executedThisRound':False,'reuseVerifiedAt':now(),'currentBinarySHA256':sha(BINARY),'currentSignature':sig.stderr},'architectureAudit':{'verdict':'pass','scope':'已重新审读需求、架构、roadmap、.spec架构与stage-3；验收仅用DebugSocket/既有真实事件自检，W3.7无产品修复因果证据','frozenCommit':COMMIT,'coreChangesSince42ccbcf':subprocess.check_output(['git','diff','--stat','42ccbcf..HEAD','--','Packages'],text=True)},'affectedSelfTests':{'reuse':old['affectedSelfTests']['reuse']},'selfTestSourceMapping':{},'memoryMonitorCheck':old['memoryMonitorCheck'],'recordingCheck':{'sourceAudit':'scripts/acceptance/recording.py 40GB准入、录前raw快照、lsof无占用后只删新增；record_scroll先汇总hitches/main-thread再删trace'},'status':'running'}
for path in old['selfTestSourceMapping']:
 mapping={ref:gitobj(ref,path) for ref in ['3e417a1','42ccbcf',COMMIT]}; assert len(set(mapping.values()))==1; data['selfTestSourceMapping'][path]=mapping
data['affectedSelfTests']['reuse']['mapping']+='；本轮 b0a28c6 对应三处 blob/tree 同样未变，复用分支行为，未声称重跑。'
save()
def run_logged(key,cmd):
 progress('command-start',key=key,command=cmd)
 log=CONTROL/(key+'.log'); started=time.monotonic()
 with log.open('w') as f: p=subprocess.Popen(cmd,stdout=f,stderr=subprocess.STDOUT,cwd=ROOT)
 while p.poll() is None:
  time.sleep(1)
 raw=log.read_text(errors='replace'); result={'command':cmd,'exitCode':p.returncode,'durationSeconds':time.monotonic()-started,'rawLog':raw,'swiftWarnings':len(re.findall(r'^.*\.swift:\d+:\d+: warning:',raw,re.M))}
 data[key]=result; save(); progress('command-end',key=key,exitCode=p.returncode,durationSeconds=result['durationSeconds'])
 return result

def selftest(name,flag):
 base=CONTROL/('selftest-'+name);base.mkdir();tmp=base/'tmp';tmp.mkdir();log=base/'app.log';socket=ROOT/'build'/('v-'+str(os.getpid())+name+'.sock')
 args=['open','-n','-a',str(APP),'--stdout',str(log),'--stderr',str(log),'--env',f'TMPDIR={tmp}/','--args',flag,'YES','-MVSelfTestFixtures',str(ROOT/'Fixtures'),'-MVSupportDirectory',str(base/'support'),'-MVCacheDirectory',str(base/'cache'),'-MVLayoutFile',str(base/'layout.json'),'-MVDebugSocket',str(socket)]
 started=time.monotonic();progress('selftest-start',name=name,command=args)
 op=subprocess.run(args,capture_output=True,text=True,timeout=30);pid=None;watch=None;code=None
 for _ in range(600):
  lines=subprocess.check_output(['ps','-axo','pid=,command='],text=True).splitlines()
  matches=[int(x.split(None,1)[0]) for x in lines if len(x.split(None,1))>1 and x.split(None,1)[1].startswith(str(BINARY)+' ') and '-MVSupportDirectory '+str(base/'support') in x]
  if matches:
   assert len(matches)==1;pid=matches[0];break
  time.sleep(.05)
 if pid:
  watch=select.kqueue();watch.control([select.kevent(pid,filter=select.KQ_FILTER_PROC,flags=select.KQ_EV_ADD|select.KQ_EV_ONESHOT,fflags=select.KQ_NOTE_EXIT|0x04000000)],0)
  progress('selftest-running',name=name,appPID=pid)
  deadline=time.monotonic()+240
  while time.monotonic()<deadline:
   ev=watch.control([],1,1)
   if ev: code=os.waitstatus_to_exitcode(ev[0].data);break
  if code is None:
   os.kill(pid,15);ev=watch.control([],1,3);code=os.waitstatus_to_exitcode(ev[0].data) if ev else None
  watch.close()
 raw=log.read_text(errors='replace') if log.exists() else ''
 result={'executed':True,'command':args,'openExitCode':op.returncode,'pid':pid,'exitCode':code,'realExitObserved':code is not None,'durationSeconds':time.monotonic()-started,'passes':sum(x.startswith('PASS ') for x in raw.splitlines()),'failures':[x for x in raw.splitlines() if x.startswith('FAIL ')],'skips':[x for x in raw.splitlines() if x.startswith('SKIP ')],'rawLog':raw,'verdict':'pass' if code==0 and 'SELFTEST OK' in raw else 'fail'}
 data['affectedSelfTests'][name]=result;save();progress('selftest-end',name=name,**{k:result[k] for k in ['pid','exitCode','passes','failures','verdict']})
 return result
selftest('viewer','-MVViewerSelfTest')
selftest('panel','-MVPanelSelfTest')
r=run_logged('unitTests',['make','test']);r['packageCounts']=[int(x) for x in re.findall(r'Test run with (\d+) tests? ',r['rawLog'])];r['tests']=sum(r['packageCounts']);assert r['exitCode']==0 and r['tests']==252 and r['swiftWarnings']==0;save()
r=run_logged('releaseBuild',['swift','build','--package-path','Packages/MacViewKit','-c','release','--product','mvbench']);binary=ROOT/'Packages/MacViewKit/.build/release/mvbench';r.update(sourceCommit=COMMIT,binary=str(binary),sha256=sha(binary),coreUnchangedSince42ccbcf=not subprocess.check_output(['git','diff','42ccbcf..HEAD','--','Packages'],text=True));assert r['exitCode']==0;save()
r=run_logged('verdictChecks',['python3','-I','scripts/acceptance/run.py','--check-verdicts']);r['cases']=len(re.findall(r'^PASS ',r['rawLog'],re.M));save()
progress('prechecks-complete',selfTests={k:v.get('verdict') for k,v in data['affectedSelfTests'].items() if k!='reuse'},tests=data['unitTests']['tests'])

